function uniqueBy(items, keyOf) {
  const seen = new Set();
  const result = [];
  for (const item of items) {
    const key = keyOf(item);
    if (!seen.has(key)) {
      seen.add(key);
      result.push(item);
    }
  }
  return result;
}

module.exports = { uniqueBy };

const { test } = require("node:test");
const assert = require("node:assert/strict");
const { uniqueBy } = require("../src/solution.cjs");

const byId = (item) => item.id;

test("keeps the first item for each duplicate key in input order", () => {
  const items = [
    { id: "b", n: 1 },
    { id: "a", n: 2 },
    { id: "b", n: 3 },
    { id: "c", n: 4 },
    { id: "a", n: 5 },
  ];
  assert.deepEqual(uniqueBy(items, byId), [
    { id: "b", n: 1 },
    { id: "a", n: 2 },
    { id: "c", n: 4 },
  ]);
});

test("treats the number 1 and the string '1' as different keys", () => {
  const items = [
    { k: 1, v: "num" },
    { k: "1", v: "str" },
    { k: 1, v: "num-dup" },
    { k: "1", v: "str-dup" },
  ];
  assert.deepEqual(uniqueBy(items, (item) => item.k), [
    { k: 1, v: "num" },
    { k: "1", v: "str" },
  ]);
});

test("handles mixed numeric and string keys together", () => {
  const keys = [2, "2", 0, "0", 2, "0", 10, "10", 10];
  assert.deepEqual(uniqueBy(keys, (k) => k), [2, "2", 0, "0", 10, "10"]);
});

test("does not mutate the input array or its items", () => {
  const items = Object.freeze([
    Object.freeze({ id: 1 }),
    Object.freeze({ id: 1 }),
    Object.freeze({ id: 2 }),
  ]);
  const snapshot = JSON.stringify(items);
  const result = uniqueBy(items, byId);
  assert.equal(JSON.stringify(items), snapshot);
  assert.equal(items.length, 3);
  assert.notEqual(result, items);
});

test("returns a new array that does not alias the input", () => {
  const items = ["x", "y"];
  const result = uniqueBy(items, (s) => s);
  assert.notEqual(result, items);
  result.push("z");
  assert.deepEqual(items, ["x", "y"]);
});

test("returns an empty array for empty input", () => {
  const items = [];
  const result = uniqueBy(items, byId);
  assert.deepEqual(result, []);
  assert.notEqual(result, items);
});

test("treats '__proto__' and other Object.prototype names as ordinary keys", () => {
  const keys = ["__proto__", "constructor", "toString", "__proto__", "constructor", "x"];
  assert.deepEqual(uniqueBy(keys, (k) => k), ["__proto__", "constructor", "toString", "x"]);
});

test("calls keyOf exactly once per item", () => {
  const calls = [];
  uniqueBy(["a", "b", "a"], (s) => {
    calls.push(s);
    return s;
  });
  assert.deepEqual(calls, ["a", "b", "a"]);
});

