    return port

import os
import sys
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))

from solution import parse_port  # noqa: E402


class ParsePortValidTests(unittest.TestCase):
    def test_lower_boundary(self):
        self.assertEqual(parse_port("1"), 1)

    def test_upper_boundary(self):
        self.assertEqual(parse_port("65535"), 65535)

    def test_common_values(self):
        self.assertEqual(parse_port("80"), 80)
        self.assertEqual(parse_port("443"), 443)
        self.assertEqual(parse_port("8080"), 8080)

    def test_returns_int(self):
        self.assertIs(type(parse_port("80")), int)

    def test_leading_zeros(self):
        self.assertEqual(parse_port("080"), 80)
        self.assertEqual(parse_port("00080"), 80)
        self.assertEqual(parse_port("0000000001"), 1)
        self.assertEqual(parse_port("0065535"), 65535)

    def test_very_long_leading_zeros(self):
        self.assertEqual(parse_port("0" * 10000 + "443"), 443)

    def test_surrounding_ascii_spaces(self):
        self.assertEqual(parse_port(" 80"), 80)
        self.assertEqual(parse_port("80 "), 80)
        self.assertEqual(parse_port("  80  "), 80)
        self.assertEqual(parse_port("   65535   "), 65535)


class ParsePortOutOfRangeTests(unittest.TestCase):
    def test_zero_rejected(self):
        with self.assertRaises(ValueError):
            parse_port("0")

    def test_all_zeros_rejected(self):
        with self.assertRaises(ValueError):
            parse_port("0000")

    def test_just_above_upper_boundary(self):
        with self.assertRaises(ValueError):
            parse_port("65536")

    def test_leading_zeros_do_not_bypass_range(self):
        with self.assertRaises(ValueError):
            parse_port("0065536")

    def test_large_values_rejected(self):
        for text in ["99999", "100000", "999999", "4294967295"]:
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_port(text)

    def test_huge_value_rejected(self):
        with self.assertRaises(ValueError):
            parse_port("9" * 5000)


class ParsePortInvalidInputTests(unittest.TestCase):
    def assertRejected(self, text):
        with self.assertRaises(ValueError, msg=repr(text)):
            parse_port(text)

    def test_empty_string(self):
        self.assertRejected("")

    def test_only_spaces(self):
        self.assertRejected("   ")

    def test_signs(self):
        for text in ["+80", "-1", "-0", "+0", " -80 ", "+"]:
            with self.subTest(text=text):
                self.assertRejected(text)

    def test_tabs(self):
        for text in ["\t80", "80\t", "\t80\t", "\t"]:
            with self.subTest(text=text):
                self.assertRejected(text)

    def test_newlines(self):
        for text in ["80\n", "\n80", "80\r\n", "\r", "8\n0"]:
            with self.subTest(text=text):
                self.assertRejected(text)

    def test_non_ascii_space(self):
        for text in [" 80", "80 ", "　 80", "80 "]:
            with self.subTest(text=text):
                self.assertRejected(text)

    def test_non_ascii_digits(self):
        for text in ["٨٠", "８０", "²"]:
            with self.subTest(text=text):
                self.assertRejected(text)

    def test_decimal_points(self):
        for text in ["80.0", ".80", "80.", "8.0.0"]:
            with self.subTest(text=text):
                self.assertRejected(text)

    def test_embedded_spaces(self):
        self.assertRejected("8 0")
        self.assertRejected("80 80")

    def test_letters_and_hex(self):
        for text in ["80a", "0x50", "abc", "8e1"]:
            with self.subTest(text=text):
                self.assertRejected(text)

    def test_non_string_inputs(self):
        for value in [None, 80, 80.0, b"80", bytearray(b"80"), ["80"], ("80",), {"port": 80}, True]:
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    parse_port(value)


if __name__ == "__main__":
    unittest.main()

