_ASCII_DIGITS = frozenset("0123456789")


def parse_port(text):
    if not isinstance(text, str):
        raise ValueError("port must be a string")
    digits = text.strip(" ")
    if not digits or not _ASCII_DIGITS.issuperset(digits):
        raise ValueError(f"invalid port: {text!r}")
    port = int(digits)
    if not 1 <= port <= 65535:
        raise ValueError(f"port out of range: {text!r}")
    return port

