class TTLCache {
  constructor(now) {
    this._now = now;
    this._entries = new Map();
  }

  set(key, value, ttlMs) {
    if (typeof ttlMs !== 'number' || !Number.isFinite(ttlMs) || ttlMs < 0) {
      throw new RangeError('ttlMs must be a nonnegative finite number');
    }
    this._entries.set(key, { value, expiresAt: this._now() + ttlMs });
  }

  get(key) {
    const entry = this._entries.get(key);
    if (entry === undefined) {
      return undefined;
    }
    if (this._now() >= entry.expiresAt) {
      this._entries.delete(key);
      return undefined;
    }
    return entry.value;
  }
}

module.exports = { TTLCache };

