const { test } = require('node:test');
const assert = require('node:assert/strict');
const { mapLimit } = require('../src/solution.cjs');

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

function controlled() {
  const calls = [];
  let inFlight = 0;
  let maxInFlight = 0;
  const fn = (item) => {
    const call = deferred();
    calls.push({ item, ...call });
    inFlight++;
    maxInFlight = Math.max(maxInFlight, inFlight);
    return call.promise.finally(() => {
      inFlight--;
    });
  };
  return {
    fn,
    calls,
    get maxInFlight() {
      return maxInFlight;
    },
  };
}

const flush = () => new Promise((resolve) => setImmediate(resolve));

test('returns results in input order when calls settle out of order', async () => {
  const h = controlled();
  const p = mapLimit(['a', 'b', 'c'], 3, h.fn);
  await flush();
  assert.equal(h.calls.length, 3);

  h.calls[2].resolve('C');
  h.calls[0].resolve('A');
  h.calls[1].resolve('B');

  assert.deepEqual(await p, ['A', 'B', 'C']);
});

