const defaultSleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function retry(operation, { attempts, delayMs = 0, sleep = defaultSleep, shouldRetry = () => true } = {}) {
  if (!Number.isInteger(attempts) || attempts < 1) {
    throw new RangeError('attempts must be a positive integer');
  }

  for (let attempt = 1; ; attempt += 1) {
    try {
      return await operation();
    } catch (error) {
      if (attempt >= attempts || !shouldRetry(error)) {
        throw error;
      }
      await sleep(delayMs);
    }
  }
}

module.exports = { retry };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { retry } = require('../src/solution.cjs');

function fakeSleep() {
  const calls = [];
  const sleep = async (ms) => {
    calls.push(ms);
  };
  return { sleep, calls };
}

function failingThenSucceeding(failures, value) {
  let calls = 0;
  const operation = async () => {
    calls += 1;
    if (calls <= failures) {
      throw new Error(`fail ${calls}`);
    }
    return value;
  };
  return { operation, getCalls: () => calls };
}

test('returns the first successful value without sleeping', async () => {
  const { sleep, calls: sleeps } = fakeSleep();
  const { operation, getCalls } = failingThenSucceeding(0, 'ok');

  const result = await retry(operation, { attempts: 3, delayMs: 50, sleep });

  assert.equal(result, 'ok');
  assert.equal(getCalls(), 1);
  assert.deepEqual(sleeps, []);
});

test('retries until success and sleeps delayMs between attempts only', async () => {
  const { sleep, calls: sleeps } = fakeSleep();
  const { operation, getCalls } = failingThenSucceeding(2, 'done');

  const result = await retry(operation, { attempts: 5, delayMs: 25, sleep });

  assert.equal(result, 'done');
  assert.equal(getCalls(), 3);
  assert.deepEqual(sleeps, [25, 25]);
});

test('throws the last error object unchanged after exhausting attempts', async () => {
  const { sleep, calls: sleeps } = fakeSleep();
  const errors = [new Error('first'), new Error('second'), new Error('third')];
  let calls = 0;
  const operation = async () => {
    const error = errors[calls];
    calls += 1;
    throw error;
  };

  await assert.rejects(
    retry(operation, { attempts: 3, delayMs: 10, sleep }),
    (error) => error === errors[2],
  );
  assert.equal(calls, 3);
  assert.deepEqual(sleeps, [10, 10]);
});

test('does not sleep after the final failure when attempts is 1', async () => {
  const { sleep, calls: sleeps } = fakeSleep();
  const error = new Error('boom');
  let calls = 0;

  await assert.rejects(
    retry(async () => {
      calls += 1;
      throw error;
    }, { attempts: 1, delayMs: 10, sleep }),
    (thrown) => thrown === error,
  );
  assert.equal(calls, 1);
  assert.deepEqual(sleeps, []);
});

test('does not retry when shouldRetry returns false', async () => {
  const { sleep, calls: sleeps } = fakeSleep();
  const fatal = new Error('fatal');
  let calls = 0;
  const seen = [];

  await assert.rejects(
    retry(async () => {
      calls += 1;
      throw fatal;
    }, {
      attempts: 5,
      delayMs: 10,
      sleep,
      shouldRetry: (error) => {
        seen.push(error);
        return false;
      },
    }),
    (thrown) => thrown === fatal,
  );
  assert.equal(calls, 1);
  assert.deepEqual(sleeps, []);
  assert.deepEqual(seen, [fatal]);
});

test('stops retrying as soon as shouldRetry returns false for a later error', async () => {
  const { sleep, calls: sleeps } = fakeSleep();
  const transient = new Error('transient');
  const permanent = new Error('permanent');
  const errors = [transient, transient, permanent];
  let calls = 0;

  await assert.rejects(
    retry(async () => {
      const error = errors[calls];
      calls += 1;
      throw error;
    }, {
      attempts: 10,
      delayMs: 5,
      sleep,
      shouldRetry: (error) => error === transient,
    }),
    (thrown) => thrown === permanent,
  );
  assert.equal(calls, 3);
  assert.deepEqual(sleeps, [5, 5]);
});

test('awaits sleep before calling the operation again', async () => {
  const events = [];
  let release;
  const gate = new Promise((resolve) => {
    release = resolve;
  });
  const sleep = async (ms) => {
    events.push(`sleep:${ms}`);
    await gate;
    events.push('sleep-resolved');
  };
  let calls = 0;
  const operation = async () => {
    calls += 1;
    events.push(`call:${calls}`);
    if (calls === 1) {
