}

function failingThenSucceeding(failures, value) {
  let calls = 0;
  const operation = async () => {
    calls += 1;
    if (calls <= failures) {
      throw new Error(`fail ${calls}`);
    }
    return value;
  };
  return { operation, count: () => calls };
}

test("returns first successful value without sleeping", async () => {
  const { sleep, calls } = fakeSleep();
  const op = failingThenSucceeding(0, "ok");

  const result = await retry(op.operation, {
    attempts: 3,
    delayMs: 100,
    sleep,
    shouldRetry: () => true,
  });

  assert.equal(result, "ok");
  assert.equal(op.count(), 1);
  assert.deepEqual(calls, []);
});

test("retries until success and sleeps only between failed attempts", async () => {
  const { sleep, calls } = fakeSleep();
  const op = failingThenSucceeding(2, "done");

  const result = await retry(op.operation, {
    attempts: 5,
    delayMs: 250,
    sleep,
    shouldRetry: () => true,
  });

  assert.equal(result, "done");
  assert.equal(op.count(), 3);
  assert.deepEqual(calls, [250, 250]);
});

test("exhaustion throws the last error object unchanged without sleeping after final failure", async () => {
  const { sleep, calls } = fakeSleep();
  const errors = [];
  let n = 0;
  const operation = async () => {
    n += 1;
    const error = new Error(`attempt ${n}`);
    errors.push(error);
    throw error;
  };

  await assert.rejects(
    retry(operation, { attempts: 3, delayMs: 10, sleep, shouldRetry: () => true }),
    (error) => {
      assert.equal(error, errors[2]);
      assert.equal(error.message, "attempt 3");
      return true;
    },
  );

  assert.equal(n, 3);
  assert.deepEqual(calls, [10, 10]);
});

