const defaultSleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

function retry(operation, { attempts, delayMs = 0, sleep = defaultSleep, shouldRetry = () => true } = {}) {
  if (!Number.isInteger(attempts) || attempts < 1) {
    throw new RangeError(`attempts must be a positive integer, got ${String(attempts)}`);
  }
  return runAttempts(operation, attempts, delayMs, sleep, shouldRetry);
}

async function runAttempts(operation, attempts, delayMs, sleep, shouldRetry) {
  for (let attempt = 1; ; attempt += 1) {
    try {
      return await operation();
    } catch (error) {
      if (attempt >= attempts || !shouldRetry(error)) {
        throw error;
      }
      await sleep(delayMs);
    }
  }
}

