      release = () => {
        events.push('wake');
        resolve();
      };
    });
  };
  let count = 0;
  const operation = async () => {
    count += 1;
    events.push(`call ${count}`);
    if (count === 1) {
      throw new Error('first');
    }
    return 'second';
  };

  const pending = retry(operation, { attempts: 2, delayMs: 7, sleep });
  await new Promise((resolve) => setImmediate(resolve));
  assert.deepEqual(events, ['call 1', 'sleep 7']);

  release();
  assert.equal(await pending, 'second');
  assert.deepEqual(events, ['call 1', 'sleep 7', 'wake', 'call 2']);
});

