import sqlite3

LIMIT_MIN = 1
LIMIT_MAX = 100


def _escape_like(text):
    return text.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")


def search(conn: sqlite3.Connection, name_prefix: str, limit: int):
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise ValueError("limit must be an integer")
    limit = min(max(limit, LIMIT_MIN), LIMIT_MAX)
    pattern = _escape_like(name_prefix) + "%"
    return conn.execute(
        "SELECT id, name FROM users WHERE name LIKE ? ESCAPE '\\' "
        "ORDER BY name, id LIMIT ?",
        (pattern, limit),
    ).fetchall()

import re

_HEADER = ["name", "age"]
_UNQUOTED_FIELD = re.compile(r'[^,\r\n]*')


def read_people(text):
    rows = _parse_rows(text)
    if not rows or rows[0] != _HEADER:
        raise ValueError("header must be exactly name,age")

    people = []
    for record_number, row in enumerate(rows[1:], start=2):
        if len(row) != 2:
            raise ValueError(f"record {record_number} has {len(row)} fields, expected 2")
        name, age = row
        people.append({"name": name, "age": _parse_age(age, record_number)})
    return people


def _parse_age(raw, record_number):
    if not (raw.isascii() and raw.isdigit()):
        raise ValueError(f"record {record_number}: age must be ASCII digits, got {raw!r}")
    age = int(raw)
    if age > 130:
        raise ValueError(f"record {record_number}: age must be 0..130, got {age}")
    return age


def _parse_rows(text):
    rows = []
    row = []
    pos = 0
    while True:
        field, pos = _read_field(text, pos)
        row.append(field)
        if pos == len(text):
            rows.append(row)
            break
        if text[pos] == ",":
            pos += 1
            continue
        pos += 2 if text.startswith("\r\n", pos) else 1
        rows.append(row)
        row = []
        if pos == len(text):
            break
    return rows


def _read_field(text, pos):
    if text.startswith('"', pos):
        return _read_quoted_field(text, pos + 1)
    end = _UNQUOTED_FIELD.match(text, pos).end()
    field = text[pos:end]
    if '"' in field:
        raise ValueError("invalid CSV quoting: quote character inside unquoted field")
    return field, end


def _read_quoted_field(text, pos):
    chunks = []
    while True:
        end = text.find('"', pos)
        if end == -1:
            raise ValueError("invalid CSV quoting: unterminated quoted field")
        chunks.append(text[pos:end])
        if text.startswith('""', end):
            chunks.append('"')
            pos = end + 2
        else:
            pos = end + 1
            break
    if pos < len(text) and text[pos] not in ",\r\n":
        raise ValueError("invalid CSV quoting: unexpected character after closing quote")
    return "".join(chunks), pos

