import re

_FIELD = re.compile(r'"((?:[^"]|"")*)"|([^",\r\n]*)')
_AGE = re.compile(r"[0-9]+")
_HEADER = ["name", "age"]
_MAX_AGE = 130


def _parse_records(text):
    records = []
    record = []
    pos = 0
    while True:
        match = _FIELD.match(text, pos)
        if match.group(1) is not None:
            record.append(match.group(1).replace('""', '"'))
        else:
            record.append(match.group(2))
        pos = match.end()
        if pos == len(text):
            records.append(record)
            return records
        if text[pos] == ",":
            pos += 1
            continue
        if text.startswith("\r\n", pos):
            pos += 2
        elif text[pos] == "\n":
            pos += 1
        else:
            raise ValueError(f"invalid CSV quoting at offset {pos}")
        records.append(record)
        record = []
        if pos == len(text):
            return records


def _parse_age(value, number):
    if not _AGE.fullmatch(value):
        raise ValueError(f"record {number}: age must be ASCII digits, got {value!r}")
    age = int(value)
    if age > _MAX_AGE:
        raise ValueError(f"record {number}: age must be 0..{_MAX_AGE}, got {age}")
    return age


def read_people(text):
    records = _parse_records(text)
    if records[0] != _HEADER:
        raise ValueError(f"header must be name,age, got {records[0]!r}")
    people = []
    for number, record in enumerate(records[1:], start=2):
        if len(record) != 2:
            raise ValueError(f"record {number}: expected 2 columns, got {len(record)}")
        name, age = record
        people.append({"name": name, "age": _parse_age(age, number)})
    return people

