async function collectPages(fetchPage) {
  const items = [];
  const requested = new Set();
  let cursor = null;

  for (;;) {
    if (cursor !== null) {
      if (requested.has(cursor)) {
        throw new Error(`collectPages: repeated cursor ${JSON.stringify(cursor)}`);
      }
      requested.add(cursor);
    }

    const page = await fetchPage(cursor);
    for (const item of page.items) {
      items.push(item);
    }

    if (page.next === null) {
      return items;
    }
    cursor = page.next;
  }
}

module.exports = { collectPages };

const { test } = require("node:test");
const assert = require("node:assert/strict");
const { collectPages } = require("../src/solution.cjs");

function scripted(pages) {
  const calls = [];
  const fetchPage = async (cursor) => {
    calls.push(cursor);
    const page = pages.get(cursor);
    if (!page) throw new Error(`unexpected cursor ${JSON.stringify(cursor)}`);
    return page;
  };
  return { fetchPage, calls };
}

test("starts with a null cursor and returns items from a single page", async () => {
  const { fetchPage, calls } = scripted(new Map([[null, { items: [1, 2], next: null }]]));
  assert.deepEqual(await collectPages(fetchPage), [1, 2]);
  assert.deepEqual(calls, [null]);
});

test("appends items from every page in order, keeping duplicates", async () => {
  const { fetchPage, calls } = scripted(
    new Map([
      [null, { items: ["a", "b", "a"], next: "c1" }],
      ["c1", { items: ["b", "c"], next: "c2" }],
      ["c2", { items: ["d"], next: null }],
