  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function copyJsonValue(value, path, ancestors) {
  if (value === null || typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    return value;
  }
  if (typeof value !== 'object') {
    throw new TypeError(`${path}: unsupported value of type ${typeof value}`);
  }
  if (ancestors.has(value)) {
    throw new TypeError(`${path}: circular reference`);
  }

  ancestors.add(value);
  try {
    if (Array.isArray(value)) {
      return value.map((item, index) => copyJsonValue(item, `${path}[${index}]`, ancestors));
    }
    if (!isPlainObject(value)) {
      throw new TypeError(`${path}: only plain objects, arrays and JSON scalars are supported`);
    }

    for (const key of Object.getOwnPropertyNames(value)) {
      if (UNSAFE_KEYS.has(key)) {
        throw new TypeError(`${path}: unsafe key "${key}"`);
      }
    }

    const copy = {};
    for (const key of Object.keys(value)) {
      copy[key] = copyJsonValue(value[key], `${path}.${key}`, ancestors);
    }
    return copy;
  } finally {
    ancestors.delete(value);
  }
}

// Mutates base, which must be a fresh copy owned by mergeConfig.
function mergeInto(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) {
    return override;
  }
  for (const key of Object.keys(override)) {
    base[key] = Object.hasOwn(base, key) ? mergeInto(base[key], override[key]) : override[key];
  }
  return base;
}

function mergeConfig(base, override) {
  const baseCopy = copyJsonValue(base, '$base', new Set());
  const overrideCopy = copyJsonValue(override, '$override', new Set());
  return mergeInto(baseCopy, overrideCopy);
}

module.exports = { mergeConfig };

