  assert.throws(() => mergeConfig({}, { f: () => {} }), TypeError);
  assert.throws(() => mergeConfig({}, { u: undefined }), TypeError);
  assert.throws(() => mergeConfig({}, { n: NaN }), TypeError);
  assert.throws(() => mergeConfig({ a: 1 }, [, 2]), TypeError);
