'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function hasOwn(object, key) {
  return Object.prototype.hasOwnProperty.call(object, key);
}

function isPlainObject(value) {
  if (value === null || typeof value !== 'object') {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function assertJsonLike(value, path) {
  if (value === null || typeof value === 'string' || typeof value === 'boolean' || typeof value === 'number') {
    return;
  }
  if (Array.isArray(value)) {
    value.forEach((item, index) => assertJsonLike(item, `${path}[${index}]`));
    return;
  }
  if (!isPlainObject(value)) {
    throw new TypeError(`Unsupported value at ${path}`);
  }
  for (const key of Reflect.ownKeys(value)) {
    if (typeof key === 'string' && UNSAFE_KEYS.has(key)) {
      throw new TypeError(`Unsafe key "${key}" at ${path}`);
    }
  }
  for (const key of Object.keys(value)) {
    assertJsonLike(value[key], `${path}.${key}`);
  }
}

function deepCopy(value) {
  if (Array.isArray(value)) {
    return value.map(deepCopy);
  }
  if (isPlainObject(value)) {
    const copy = {};
    for (const key of Object.keys(value)) {
      copy[key] = deepCopy(value[key]);
    }
    return copy;
  }
  return value;
}

function mergeValues(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) {
    return deepCopy(override);
  }
  const result = {};
  for (const key of Object.keys(base)) {
    result[key] = hasOwn(override, key)
      ? mergeValues(base[key], override[key])
      : deepCopy(base[key]);
  }
  for (const key of Object.keys(override)) {
    if (!hasOwn(base, key)) {
      result[key] = deepCopy(override[key]);
    }
  }
  return result;
}

function mergeConfig(base, override) {
  assertJsonLike(base, 'base');
  assertJsonLike(override, 'override');
  return mergeValues(base, override);
}

module.exports = { mergeConfig };

'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { mergeConfig } = require('../src/solution.cjs');

function deepFreeze(value) {
  if (value !== null && typeof value === 'object') {
    Object.values(value).forEach(deepFreeze);
    Object.freeze(value);
  }
  return value;
}

function collectContainers(value, into = new Set()) {
  if (value !== null && typeof value === 'object') {
    if (!into.has(value)) {
      into.add(value);
      Object.values(value).forEach((child) => collectContainers(child, into));
    }
  }
  return into;
}

function withKey(key, value) {
  return Object.defineProperty({}, key, { value, enumerable: true, writable: true, configurable: true });
}

describe('nested merges', () => {
  it('merges plain objects recursively and keeps untouched base keys', () => {
    const base = { name: 'x', server: { host: 'a', port: 1, tls: { enabled: false } } };
    const override = { server: { port: 2, tls: { enabled: true } } };
    assert.deepEqual(mergeConfig(base, override), {
      name: 'x',
      server: { host: 'a', port: 2, tls: { enabled: true } },
    });
  });

  it('adds keys that exist only in override at any depth', () => {
    const base = { server: { tls: { enabled: true } } };
    const override = { extra: 1, server: { tls: { cert: 'c' } } };
    assert.deepEqual(mergeConfig(base, override), {
      extra: 1,
      server: { tls: { enabled: true, cert: 'c' } },
    });
  });

  it('copies override-only objects into an empty base', () => {
    assert.deepEqual(mergeConfig({}, { a: { b: { c: 1 } } }), { a: { b: { c: 1 } } });
  });

  it('returns a copy of base when override is empty', () => {
    const base = { a: { b: [1, { c: 2 }] } };
    assert.deepEqual(mergeConfig(base, {}), base);
  });
});

describe('replacement', () => {
  it('replaces arrays instead of merging them', () => {
    const base = { list: [1, 2, 3], nested: { items: [{ a: 1 }] } };
    const override = { list: [4], nested: { items: [{ b: 2 }] } };
    assert.deepEqual(mergeConfig(base, override), {
      list: [4],
      nested: { items: [{ b: 2 }] },
    });
  });

  it('replaces an object with a scalar', () => {
    assert.deepEqual(mergeConfig({ a: { b: 1 } }, { a: 5 }), { a: 5 });
  });

  it('replaces a scalar with an object', () => {
    assert.deepEqual(mergeConfig({ a: 5 }, { a: { b: 1 } }), { a: { b: 1 } });
  });

  it('replaces an object with null', () => {
    assert.deepEqual(mergeConfig({ a: { b: 1 } }, { a: null }), { a: null });
  });

  it('replaces an array with an object and an object with an array', () => {
    assert.deepEqual(mergeConfig({ a: [1] }, { a: { b: 1 } }), { a: { b: 1 } });
    assert.deepEqual(mergeConfig({ a: { b: 1 } }, { a: [1] }), { a: [1] });
  });

  it('replaces scalars with falsy values', () => {
    assert.deepEqual(
      mergeConfig({ a: 1, b: 'x', c: true }, { a: 0, b: '', c: false }),
      { a: 0, b: '', c: false },
    );
  });

  it('replaces a top-level array with an array', () => {
    assert.deepEqual(mergeConfig([1, 2], [3]), [3]);
  });
});

describe('inputs and aliasing', () => {
  it('does not mutate frozen inputs', () => {
    const base = deepFreeze({ a: { b: 1 }, keep: { y: [1, 2] } });
    const override = deepFreeze({ a: { c: 2 }, list: [{ z: 1 }] });
    const baseSnapshot = structuredClone(base);
    const overrideSnapshot = structuredClone(override);

    mergeConfig(base, override);

    assert.deepEqual(base, baseSnapshot);
    assert.deepEqual(override, overrideSnapshot);
  });

  it('shares no nested arrays or objects with either input', () => {
    const base = { a: { b: { c: 1 } }, arr: [{ x: 1 }], keep: { y: [1, 2] } };
    const override = { a: { d: [{ z: 1 }] }, arr: [{ w: 2 }] };
    const result = mergeConfig(base, override);

    const inputContainers = new Set([
      ...collectContainers(base),
      ...collectContainers(override),
    ]);
    for (const container of collectContainers(result)) {
      assert.equal(inputContainers.has(container), false);
    }
  });

  it('copies base-only and override-only subtrees', () => {
    const base = { keep: { y: [1, 2] } };
    const override = { add: { z: [3] } };
    const result = mergeConfig(base, override);

    assert.notEqual(result.keep, base.keep);
    assert.notEqual(result.keep.y, base.keep.y);
    assert.notEqual(result.add, override.add);
    assert.notEqual(result.add.z, override.add.z);
  });

  it('keeps result independent when it is mutated', () => {
    const base = { keep: { y: [1, 2] }, a: { b: { c: 1 } } };
    const override = { list: [{ v: 1 }] };
    const result = mergeConfig(base, override);

    result.keep.y.push(3);
    result.a.b.c = 9;
    result.list[0].v = 9;

    assert.deepEqual(base, { keep: { y: [1, 2] }, a: { b: { c: 1 } } });
    assert.deepEqual(override, { list: [{ v: 1 }] });
  });

  it('keeps result independent when an input is mutated afterwards', () => {
    const base = { keep: { y: [1, 2] } };
    const override = { list: [{ v: 1 }] };
    const result = mergeConfig(base, override);

    base.keep.y.push(3);
    override.list[0].v = 9;

    assert.deepEqual(result, { keep: { y: [1, 2] }, list: [{ v: 1 }] });
  });

  it('gives separate copies to repeated references within an input', () => {
    const shared = { v: 1 };
    const result = mergeConfig({ a: shared, b: shared }, {});

    assert.notEqual(result.a, result.b);
    result.a.v = 2;
    assert.equal(result.b.v, 1);
    assert.equal(shared.v, 1);
  });
});

describe('unsafe keys', () => {
  it('rejects own __proto__ in override without polluting Object.prototype', () => {
    const override = JSON.parse('{"__proto__": {"polluted": true}}');
    assert.throws(() => mergeConfig({}, override), TypeError);
    assert.equal({}.polluted, undefined);
  });

  it('rejects own __proto__ in base', () => {
    const base = JSON.parse('{"__proto__": {"polluted": true}}');
    assert.throws(() => mergeConfig(base, {}), TypeError);
  });

  it('rejects constructor and prototype keys at top level in either input', () => {
    for (const key of ['__proto__', 'constructor', 'prototype']) {
      assert.throws(() => mergeConfig(withKey(key, 1), {}), TypeError, key);
      assert.throws(() => mergeConfig({}, withKey(key, 1)), TypeError, key);
    }
  });

  it('rejects unsafe keys deeply nested in objects', () => {
    const base = { a: { b: { c: {} } } };
    const override = { a: { b: { c: withKey('constructor', {}) } } };
    assert.throws(() => mergeConfig(base, override), TypeError);
  });

  it('rejects unsafe keys inside arrays', () => {
    assert.throws(
      () => mergeConfig({ list: [{ ok: 1 }] }, { list: [{ constructor: 1 }] }),
      TypeError,
    );
    assert.throws(
      () => mergeConfig({ list: [[{ prototype: {} }]] }, {}),
      TypeError,
    );
  });

  it('rejects unsafe keys in a base subtree that override does not mention', () => {
    assert.throws(() => mergeConfig({ a: withKey('__proto__', 1) }, { b: 1 }), TypeError);
  });

  it('rejects unsafe keys inside an override value that replaces a base value', () => {
    assert.throws(
      () => mergeConfig({ a: 1 }, { a: { nested: withKey('prototype', {}) } }),
      TypeError,
    );
  });

  it('allows ordinary keys that share names with Object.prototype members', () => {
    const result = mergeConfig({}, { hasOwnProperty: 1, toString: 'x' });
    assert.equal(Object.getPrototypeOf(result), Object.prototype);
    assert.deepEqual(Object.keys(result), ['hasOwnProperty', 'toString']);
    assert.equal(result.hasOwnProperty, 1);
  });
});

describe('unsupported values', () => {
  it('rejects undefined, functions, and non-plain objects', () => {
    assert.throws(() => mergeConfig({}, { a: undefined }), TypeError);
    assert.throws(() => mergeConfig({}, { a: () => 1 }), TypeError);
    assert.throws(() => mergeConfig({ a: new Date(0) }, {}), TypeError);
    class Thing {}
    assert.throws(() => mergeConfig({}, { a: new Thing() }), TypeError);
  });
});

'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPrimitive(value) {
  return value === null || typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean';
}

function isPlainObject(value) {
  if (value === null || typeof value !== 'object') return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function isOwnEnumerable(obj, key) {
  return Object.prototype.propertyIsEnumerable.call(obj, key);
}

function assertNoUnsafeKeys(obj) {
  for (const key of Object.getOwnPropertyNames(obj)) {
    if (UNSAFE_KEYS.has(key)) {
      throw new TypeError(`Unsafe key "${key}" is not allowed`);
    }
  }
}

// Both inputs are validated in full before copying, so an unsafe key in a base subtree
// that the override replaces is still rejected.
function assertJsonLike(value) {
  if (isPrimitive(value)) return;
  if (Array.isArray(value)) {
    assertNoUnsafeKeys(value);
    for (let i = 0; i < value.length; i++) assertJsonLike(value[i]);
    return;
  }
  if (isPlainObject(value)) {
    assertNoUnsafeKeys(value);
    for (const key of Object.keys(value)) assertJsonLike(value[key]);
    return;
  }
  throw new TypeError(`Unsupported config value of type ${typeof value}`);
}

function deepCopy(value) {
  if (isPrimitive(value)) return value;
  if (Array.isArray(value)) return Array.from(value, (item) => deepCopy(item));
  const copy = {};
  for (const key of Object.keys(value)) copy[key] = deepCopy(value[key]);
  return copy;
}

function mergeValues(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) return deepCopy(override);
  const merged = {};
  for (const key of Object.keys(base)) {
    merged[key] = isOwnEnumerable(override, key)
      ? mergeValues(base[key], override[key])
      : deepCopy(base[key]);
  }
  for (const key of Object.keys(override)) {
    if (!isOwnEnumerable(base, key)) merged[key] = deepCopy(override[key]);
  }
  return merged;
}

function mergeConfig(base, override) {
  assertJsonLike(base);
  assertJsonLike(override);
  return mergeValues(base, override);
}

module.exports = { mergeConfig };

'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { mergeConfig } = require('../src/solution.cjs');

const UNSAFE_KEYS = ['__proto__', 'constructor', 'prototype'];

function containers(value, out = []) {
  if (value !== null && typeof value === 'object') {
    out.push(value);
    for (const child of Object.values(value)) containers(child, out);
  }
  return out;
}

