  };
  const override = { server: { port: 8080, tls: { enabled: true } }, debug: true };
  assert.deepEqual(mergeConfig(base, override), {
    server: { host: 'localhost', port: 8080, tls: { enabled: true, cert: 'a.pem' } },
    name: 'app',
    debug: true,
  });
});

