  const base = { a: { b: 1 }, c: 'x', d: 5, e: true };
  const override = { a: 2, c: { y: 1 }, d: null, e: [1] };
  assert.deepEqual(mergeConfig(base, override), {
    a: 2,
    c: { y: 1 },
    d: null,
    e: [1],
  });
});

