  assert.deepEqual(mergeConfig(base, override), {
    a: { b: { c: 1 }, z: 1 },
    keep: [1, { x: 2 }],
  });
});

test('handles keys that exist on Object.prototype as ordinary keys', () => {
  assert.deepEqual(mergeConfig({ valueOf: { a: 1 } }, { valueOf: { b: 2 } }), {
    valueOf: { a: 1, b: 2 },
  });
  assert.deepEqual(mergeConfig({ toString: { a: 1 } }, {}), { toString: { a: 1 } });
