'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && Object.getPrototypeOf(value) === Object.prototype;
}

function assertJsonLike(value) {
  if (Array.isArray(value)) {
    for (const item of value) assertJsonLike(item);
    return;
  }
  if (isPlainObject(value)) {
    for (const key of Object.getOwnPropertyNames(value)) {
      if (UNSAFE_KEYS.has(key)) {
        throw new Error(`Unsafe key "${key}" is not allowed`);
      }
      assertJsonLike(value[key]);
    }
    return;
  }
  if (value !== null && (typeof value === 'object' || typeof value === 'function')) {
    throw new TypeError(`Unsupported value: ${Object.prototype.toString.call(value)}`);
  }
}

function cloneValue(value) {
  if (Array.isArray(value)) return value.map(cloneValue);
  if (isPlainObject(value)) {
    const result = {};
    for (const key of Object.keys(value)) result[key] = cloneValue(value[key]);
    return result;
  }
  return value;
}

function mergeValues(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) return cloneValue(override);

  const result = {};
  for (const key of Object.keys(base)) {
    result[key] = Object.hasOwn(override, key)
      ? mergeValues(base[key], override[key])
      : cloneValue(base[key]);
  }
  for (const key of Object.keys(override)) {
    if (!Object.hasOwn(base, key)) result[key] = cloneValue(override[key]);
  }
  return result;
}

function mergeConfig(base, override) {
  assertJsonLike(base);
  assertJsonLike(override);
  return mergeValues(base, override);
}

module.exports = { mergeConfig };

