  assert.throws(() => splitCents(1, [Number.MAX_SAFE_INTEGER, 1]), RangeError);
});

function assertValidInput(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a nonempty array');
  }
  let weightSum = 0;
  for (const weight of weights) {
    if (!Number.isSafeInteger(weight) || weight <= 0) {
      throw new RangeError('weights must be positive safe integers');
    }
    weightSum += weight;
    if (!Number.isSafeInteger(weightSum)) {
      throw new RangeError('sum of weights must be a safe integer');
    }
    if (!Number.isSafeInteger(total * weight)) {
      throw new RangeError('total * weight must be a safe integer');
    }
  }
  return weightSum;
}

function splitCents(total, weights) {
  const weightSum = assertValidInput(total, weights);
  const exactTotal = BigInt(total);
  const exactWeightSum = BigInt(weightSum);

  const shares = [];
  const remainders = [];
  let allocated = 0n;
  for (const weight of weights) {
    const numerator = exactTotal * BigInt(weight);
    const floor = numerator / exactWeightSum;
    shares.push(floor);
    remainders.push(numerator % exactWeightSum);
    allocated += floor;
  }

  const leftover = Number(exactTotal - allocated);
  const order = shares.map((_, index) => index);
  order.sort((a, b) => {
    if (remainders[a] !== remainders[b]) {
      return remainders[a] > remainders[b] ? -1 : 1;
    }
    return a - b;
  });
  for (let k = 0; k < leftover; k++) {
    shares[order[k]] += 1n;
  }

  return shares.map(Number);
}

