'use strict';

function assertSafeInteger(value, min, name) {
  if (!Number.isSafeInteger(value) || value < min) {
    throw new RangeError(`${name} must be a safe integer >= ${min}`);
  }
}

function splitCents(total, weights) {
  assertSafeInteger(total, 0, 'total');
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a nonempty array');
  }

  let weightSum = 0;
  for (const weight of weights) {
    assertSafeInteger(weight, 1, 'weight');
    weightSum += weight;
    if (!Number.isSafeInteger(weightSum)) {
      throw new RangeError('sum of weights must be a safe integer');
    }
    if (!Number.isSafeInteger(total * weight)) {
      throw new RangeError('total * weight must be a safe integer');
    }
  }

  const exactTotal = BigInt(total);
  const exactSum = BigInt(weightSum);
  const products = weights.map((weight) => exactTotal * BigInt(weight));
  const quotas = products.map((product) => product / exactSum);
  const remainders = products.map((product) => product % exactSum);

  let leftover = exactTotal;
  for (const quota of quotas) {
    leftover -= quota;
  }

  const order = weights.map((_, index) => index);
  order.sort((a, b) => {
    if (remainders[a] !== remainders[b]) {
      return remainders[a] > remainders[b] ? -1 : 1;
    }
    return a - b;
  });

  for (let k = 0; k < Number(leftover); k++) {
    quotas[order[k]] += 1n;
  }

  return quotas.map(Number);
}

