const MAX = Number.MAX_SAFE_INTEGER;

function invalid(message) {
  return new RangeError(message);
}

function validate(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw invalid("total must be a nonnegative safe integer");
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw invalid("weights must be a nonempty array");
  }

  let sum = 0;
  for (let i = 0; i < weights.length; i++) {
    const w = weights[i];
    if (!Number.isSafeInteger(w) || w <= 0) {
      throw invalid(`weights[${i}] must be a positive safe integer`);
    }
    sum += w;
    if (sum > MAX) {
      throw invalid("sum of weights exceeds the safe integer range");
    }
    if (total * w > MAX) {
      throw invalid(`total * weights[${i}] exceeds the safe integer range`);
    }
  }
}

function splitCents(total, weights) {
  validate(total, weights);

  let weightSum = 0;
  for (const w of weights) weightSum += w;

  const shares = weights.map((w, index) => {
    const product = total * w;
    const remainder = product % weightSum;
    return { index, quota: (product - remainder) / weightSum, remainder };
  });

  const allocated = shares.reduce((acc, s) => acc + s.quota, 0);
  let leftover = total - allocated;

  const byRemainder = [...shares].sort(
    (a, b) => b.remainder - a.remainder || a.index - b.index,
  );
  for (const share of byRemainder) {
    if (leftover === 0) break;
    share.quota += 1;
    leftover -= 1;
  }

  return shares.map((s) => s.quota);
}

