import re
from datetime import datetime, timedelta, timezone

_TIMESTAMP = re.compile(
    r"(?P<year>[0-9]{4})-(?P<month>[0-9]{2})-(?P<day>[0-9]{2})"
    r"T(?P<hour>[0-9]{2}):(?P<minute>[0-9]{2}):(?P<second>[0-9]{2})(?:\.[0-9]+)?"
    r"(?P<offset>Z|(?P<sign>[+-])(?P<off_hour>[0-9]{2}):(?P<off_minute>[0-9]{2}))"
)


def utc_day_start(text):
    if not isinstance(text, str):
        raise ValueError("timestamp must be a string")
    match = _TIMESTAMP.fullmatch(text)
    if match is None:
        raise ValueError(f"not an ISO 8601 timestamp with Z or a numeric offset: {text!r}")

    if match["offset"] == "Z":
        tz = timezone.utc
    else:
        off_hour = int(match["off_hour"])
        off_minute = int(match["off_minute"])
        if off_hour > 23 or off_minute > 59:
            raise ValueError(f"UTC offset out of range: {text!r}")
        delta = timedelta(hours=off_hour, minutes=off_minute)
        tz = timezone(-delta if match["sign"] == "-" else delta)

    try:
        local = datetime(
            int(match["year"]),
            int(match["month"]),
            int(match["day"]),
            int(match["hour"]),
            int(match["minute"]),
            int(match["second"]),
            tzinfo=tz,
        )
        utc = local.astimezone(timezone.utc)
    except (ValueError, OverflowError) as exc:
        raise ValueError(f"invalid timestamp: {text!r}") from exc

    return datetime(utc.year, utc.month, utc.day, tzinfo=timezone.utc)

