  let count = 0;
  const listener = () => count++;

  const firstUnsubscribe = emitter.on("tick", listener);
  firstUnsubscribe();
  emitter.on("tick", listener);
  firstUnsubscribe();
  emitter.emit("tick");

  assert.equal(count, 1);
});

