  const emitter = new Emitter();
  const calls = [];
  let unsubscribeB;
  emitter.on("tick", () => {
    calls.push("a");
    unsubscribeB();
  });
  unsubscribeB = emitter.on("tick", () => calls.push("b"));

  emitter.emit("tick");
  assert.deepEqual(calls, ["a", "b"]);

  emitter.emit("tick");
  assert.deepEqual(calls, ["a", "b", "a"]);
});

test("off during emit affects only later emits", () => {
  const emitter = new Emitter();
  const calls = [];
  const b = () => calls.push("b");
  emitter.on("tick", () => {
    calls.push("a");
    emitter.off("tick", b);
  });
  emitter.on("tick", b);

  emitter.emit("tick");
  assert.deepEqual(calls, ["a", "b"]);

  emitter.emit("tick");
  assert.deepEqual(calls, ["a", "b", "a"]);
});

test("a listener added during emit is not called in that emit but is called later", () => {
  const emitter = new Emitter();
  const calls = [];
  const added = () => calls.push("added");
  emitter.on("tick", () => {
    calls.push("a");
    emitter.on("tick", added);
  });

  emitter.emit("tick");
  assert.deepEqual(calls, ["a"]);

  emitter.emit("tick");
  assert.deepEqual(calls, ["a", "a", "added"]);
});

test("a listener removed and re-added during emit keeps its place for later emits", () => {
  const emitter = new Emitter();
  const calls = [];
  const b = () => calls.push("b");
  emitter.on("tick", () => {
    calls.push("a");
    emitter.off("tick", b);
    emitter.on("tick", b);
  });
  emitter.on("tick", b);

  emitter.emit("tick");
  assert.deepEqual(calls, ["a", "b"]);

  calls.length = 0;
  emitter.emit("tick");
  assert.deepEqual(calls, ["a", "b"]);
});

