'use strict';

class Emitter {
  #listeners = new Map();

  on(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('listener must be a function');
    }
    const entries = this.#listeners.get(event) ?? [];
    if (entries.some((entry) => entry.fn === fn)) {
      return () => {};
    }
    // Handles are bound to this entry, so a stale handle cannot remove a later re-registration.
    const entry = { fn };
    entries.push(entry);
    this.#listeners.set(event, entries);
    return () => this.#remove(event, entry);
  }

  emit(event, value) {
    const entries = this.#listeners.get(event);
    if (!entries) return;
    for (const { fn } of entries.slice()) {
      fn(value);
    }
  }

  off(event, fn) {
    const entries = this.#listeners.get(event);
    if (!entries) return;
    const entry = entries.find((candidate) => candidate.fn === fn);
    if (entry) this.#remove(event, entry);
  }

  #remove(event, entry) {
    const entries = this.#listeners.get(event);
    if (!entries) return;
    const index = entries.indexOf(entry);
    if (index === -1) return;
    entries.splice(index, 1);
    if (entries.length === 0) this.#listeners.delete(event);
  }
}

