class Emitter {
  #events = new Map();

  on(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('listener must be a function');
    }
    const entries = this.#events.get(event) ?? [];
    if (entries.some((entry) => entry.fn === fn)) {
      return () => {};
    }
    const entry = { fn };
    entries.push(entry);
    this.#events.set(event, entries);
    return () => this.#remove(event, entry);
  }

  off(event, fn) {
    const entry = (this.#events.get(event) ?? []).find((e) => e.fn === fn);
    if (entry) {
      this.#remove(event, entry);
    }
  }

  emit(event, value) {
    const entries = this.#events.get(event);
    if (!entries) {
      return;
    }
    for (const entry of entries.slice()) {
      entry.fn(value);
    }
  }

  #remove(event, entry) {
    const entries = this.#events.get(event);
    if (!entries) {
      return;
    }
    const index = entries.indexOf(entry);
    if (index === -1) {
      return;
    }
    entries.splice(index, 1);
    if (entries.length === 0) {
      this.#events.delete(event);
    }
  }
}

