class Emitter {
  #listeners = new Map();

  on(event, fn) {
    let records = this.#listeners.get(event);
    if (!records) {
      records = [];
      this.#listeners.set(event, records);
    }

    let record = records.find((r) => r.fn === fn);
    if (!record) {
      record = { fn };
      records.push(record);
    }

    return () => this.#remove(event, record);
  }

  off(event, fn) {
    const records = this.#listeners.get(event);
    if (!records) return;

    const record = records.find((r) => r.fn === fn);
    if (record) this.#remove(event, record);
  }

  emit(event, value) {
    const records = this.#listeners.get(event);
    if (!records) return;

    for (const record of records.slice()) {
      record.fn(value);
    }
  }

  #remove(event, record) {
    const records = this.#listeners.get(event);
    if (!records) return;

    const index = records.indexOf(record);
    if (index === -1) return;

    records.splice(index, 1);
    if (records.length === 0) this.#listeners.delete(event);
  }
}

