from pathlib import Path, PurePath


def resolve_upload(root, supplied):
    """Advisory check only: a symlink swapped in after this call can still redirect a later write."""
    base = Path(root).resolve(strict=True)
    rel = PurePath(supplied)
    if rel.is_absolute() or rel.drive or rel.root:
        raise ValueError(f"absolute path not allowed: {supplied!r}")
    target = (base / rel).resolve(strict=False)
    if target == base:
        raise ValueError(f"path refers to root: {supplied!r}")
    if not target.is_relative_to(base):
        raise ValueError(f"path escapes root: {supplied!r}")
    return target

