import os
import sys
import tempfile
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))

from solution import resolve_upload


class ResolveUploadTests(unittest.TestCase):
    def setUp(self):
        tmp = tempfile.TemporaryDirectory()
        self.addCleanup(tmp.cleanup)
        base = Path(tmp.name).resolve()
        self.root = base / "root"
        self.sibling = base / "root-sibling"
        self.root.mkdir()
        self.sibling.mkdir()
        (self.sibling / "secret.txt").write_text("secret")

    def test_accepts_plain_and_nested_names(self):
        self.assertEqual(resolve_upload(self.root, "file.txt"), self.root / "file.txt")
        self.assertEqual(
            resolve_upload(self.root, "a/b/c.txt"), self.root / "a" / "b" / "c.txt"
        )

    def test_accepts_string_root(self):
        self.assertEqual(
            resolve_upload(str(self.root), "file.txt"), self.root / "file.txt"
        )

    def test_accepts_existing_file_inside_root(self):
        (self.root / "present.txt").write_text("x")
        self.assertEqual(
            resolve_upload(self.root, "present.txt"), self.root / "present.txt"
        )

    def test_returns_resolved_path_for_dotted_inside_path(self):
        self.assertEqual(
            resolve_upload(self.root, "a/../b.txt"), self.root / "b.txt"
        )

    def test_does_not_create_anything(self):
        resolve_upload(self.root, "a/b/c.txt")
        self.assertEqual(os.listdir(self.root), [])

    def test_rejects_absolute_path(self):
        with self.assertRaises(ValueError):
            resolve_upload(self.root, str(self.sibling / "secret.txt"))

    def test_rejects_root_itself(self):
        for supplied in ("", ".", "a/.."):
            with self.subTest(supplied=supplied):
                with self.assertRaises(ValueError):
                    resolve_upload(self.root, supplied)

    def test_rejects_traversal_including_shared_name_prefix(self):
        for supplied in (
            "..",
            "../new.txt",
            "../root-sibling/secret.txt",
            "a/../../root-sibling/secret.txt",
        ):
            with self.subTest(supplied=supplied):
                with self.assertRaises(ValueError):
                    resolve_upload(self.root, supplied)

    def test_rejects_symlinked_directory_pointing_outside(self):
        os.symlink(self.sibling, self.root / "link", target_is_directory=True)
        for supplied in ("link", "link/secret.txt", "link/new.txt"):
            with self.subTest(supplied=supplied):
                with self.assertRaises(ValueError):
                    resolve_upload(self.root, supplied)

    def test_rejects_symlinked_file_pointing_outside(self):
        os.symlink(self.sibling / "secret.txt", self.root / "file-link")
        with self.assertRaises(ValueError):
            resolve_upload(self.root, "file-link")

    def test_accepts_symlink_pointing_inside_root(self):
        (self.root / "real").mkdir()
        os.symlink(self.root / "real", self.root / "alias", target_is_directory=True)
        self.assertEqual(
            resolve_upload(self.root, "alias/x.txt"), self.root / "real" / "x.txt"
        )


if __name__ == "__main__":
    unittest.main()

