from pathlib import Path, PurePath


def resolve_upload(root, supplied):
    root_path = Path(root).resolve()
    supplied_path = PurePath(supplied)

    if supplied_path.is_absolute() or supplied_path.drive or supplied_path.root:
        raise ValueError("absolute paths are not allowed")

    target = (root_path / supplied_path).resolve()

    if target == root_path:
        raise ValueError("target must not be the root directory")
    if not target.is_relative_to(root_path):
        raise ValueError("target resolves outside the root directory")

    return target
